import * as React from "react";
import { useState } from "react";
import NormalTextLink from "../normalTextLink/NormalTextLink";
import { MpaIcon } from "../icon/MpaIcon";

export interface TopNavRightItemProps {
    navItem:{
        label : string,
        link?: string,
        header?: string,
        desc?: string
    }
    hasSubMenu?: boolean,
    index: number,
    layout: string
}


const TopNavRightItem: React.FC<TopNavRightItemProps> = ({
    navItem,
    hasSubMenu,
    index,
    layout
}) => {

    const [openItem, setOpenItem] = useState<number | null>(null);
        
    const handleHeaderClick = (index:number) => {
        setOpenItem(openItem === index ? null : index);
    };

    return (
        <>
            {layout == "mega-menu" && (
                <div className="columns-nav-title"> 
                    {navItem?.label && <span> <NormalTextLink id="normalTextLinkId" href={navItem?.link}>{navItem?.label}</NormalTextLink> </span>} 
                    {navItem?.header && <span className="nav-header"> {navItem?.header} </span>} 
                    {navItem?.desc && <span className="nav-desc"> {navItem?.desc} </span>}
                    <span className="find-link">
                    <NormalTextLink id="normalTextLinkId" href={navItem?.link}>Find Out more 
                        <MpaIcon iconName={'ChevronRight'}/>
                   </NormalTextLink> </span>
                </div>
            )}

            {layout == "mega-menu-2" && (
                <div className={`second-header ${openItem === index ? 'selected' : '' }`}>
                    {navItem?.label && (<NormalTextLink id="normalTextLinkId" href={navItem?.link}><h3 className="column-header" onClick={() => handleHeaderClick(index)}>{navItem.label}</h3></NormalTextLink> )} 
                    {hasSubMenu && ( 
                    <span>
                        <MpaIcon iconName={'ChevronRight'}/>                            
                    </span>)}
                </div> 
            )}
        </>
    );
};

export default TopNavRightItem;
